/**
 * Page-level list of form errors after a failed submit (`design/components/error-summary.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/error-summary.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  Icon,
  agentMember,
  chooseListItem,
  claimSlot,
  createDerived,
  elementRef,
  listItems,
  scope,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/error-summary.module.css'

export interface ErrorSummaryError {
  label: string
  fieldId: string
}

export interface ErrorSummaryProps {
  /**
   * Errors in form order, the navigation order (Stat's rule); an empty list renders nothing.
   */
  errors: ErrorSummaryError[]
  /**
   * Text from the app ("The ticket can't be raised yet"); the vocabulary writes no error copy.
   */
  title: string
}

/** Page-level list of form errors after a failed submit. */
export default function ErrorSummary(given: ErrorSummaryProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const list = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const follow = createDerived(() => (event: MouseEvent, fieldId: string) => {
      const control = document.getElementById(fieldId)
      if (control === null) return
      event.preventDefault()
      control.focus()
      control.scrollIntoView({ block: 'nearest' })
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'ErrorSummary',
        element: () => root.value,
        state: () => ({ items: listItems(list.value, styles.link) }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) => chooseListItem(list.value, styles.link, value),
          },
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <>
        {props.errors.length > 0 ? (
          <div class={styles.root} role="alert" data-member="error-summary" ref={root.attach}>
            {/* glyph */}
            <span class={styles.glyph}>
              <Icon name="error" size="md" />
            </span>
            {/* body */}
            <div class={styles.body}>
              {/* title */}
              <p class={styles.title}>{props.title}</p>
              {/* list */}
              <ul class={styles.list} ref={list.attach}>
                <Each of={props.errors} by={(error, at) => `${at}-${error.fieldId}`} renew>
                  {(error) => (
                    <li>
                      {/* entry */}
                      <a
                        class={styles.link}
                        href={`#${error.fieldId}`}
                        onclick={($event: MouseEvent) => follow.value($event, error.fieldId)}
                      >
                        {error.label}
                      </a>
                    </li>
                  )}
                </Each>
              </ul>
            </div>
          </div>
        ) : null}
      </>
    )
  })
}
